@Transactional
public ReadingResponse submitReading(String batchKey, SubmitReadingRequest request) {
    String key = Inputs.requireText(batchKey, "batchKey");
    String readingKey = Inputs.requireText(request.readingKey(), "readingKey");
    Instant measuredAt = Inputs.requireInstant(request.measuredAt(), "measuredAt");
    BigDecimal reading = Inputs.requireDecimal(request.reading(), "reading");
    String submittedBy = Inputs.requireText(request.submittedBy(), "submittedBy");
    String fingerprint = String.join("|", key, readingKey, measuredAt.toString(), reading.toPlainString(), submittedBy);
    return idempotency.execute(request.requestId(), fingerprint, ReadingResponse.class, () -> {
        Batch batch = batches.findByKeyForUpdate(key).orElseThrow(() -> notFound("批次不存在: " + key));
        int revision = batch.revision();
        if (batch.status() == BatchStatus.RELEASED) {
            revision = batch.revision() + 1;
            batches.reopenWithNewRevision(batch.id(), revision);
        }
        Certificate cert = certificates.findMatching(batch.instrumentId(), measuredAt)
            .orElseThrow(() -> ApiException.unprocessable("测量时刻无匹配的有效证书: instrument=" + batch.instrumentId()));
        Certificate lockedCert = certificates.findByIdForUpdate(cert.id()).orElseThrow();
        if (lockedCert.revoked()) throw unprocessable(...); // revoke committed between match and lock
        BatchReading br = new BatchReading(0, readingKey, batch.id(), measuredAt, reading, submittedBy,
            lockedCert.id(), lockedCert.version(), revision, false, Instant.now(clock));
        long readingId;
        try { readingId = readings.insert(br); } catch (DuplicateKeyException e) { throw conflict("DUPLICATE_READING_KEY", ...); }
        // outlier detection
        BigDecimal deviation = reading.subtract(batch.targetValue()).abs();
        Long outlierId = null;
        if (deviation.compareTo(batch.tolerance()) > 0) {
            OutlierRecord outlier = new OutlierRecord(0, batch.id(), readingId, revision, batch.targetValue(),
                batch.tolerance(), reading, deviation, OutlierStatus.PENDING, Instant.now(clock), null);
            outlierId = outliers.insert(outlier);
        }
        recordStats(batch.id(), revision, "SUBMIT");
        return new ReadingResponse(readingId, readingKey, key, measuredAt, DtoMapper.format(reading), submittedBy,
            lockedCert.id(), lockedCert.version(), revision, false, outlierId,
            outlierId == null ? null : DtoMapper.format(deviation), ...createdAt);
    });
}
