        BatchReading br = new BatchReading(0, readingKey, batch.id(), measuredAt, reading, submittedBy,
            lockedCert.id(), lockedCert.version(), revision, false, Instant.now(clock));
        long readingId;
        try { readingId = readings.insert(br); } catch (DuplicateKeyException e) { throw conflict("DUPLICATE_READING_KEY", ...); }
        // outlier detection
        BigDecimal deviation = reading.subtract(batch.targetValue()).abs();
        Long outlierId = null;
