public BatchStatsRecord recordStats(long batchId, int revision, String trigger) {
    List<BatchReading> all = readings.findByBatchId(batchId);
    List<BatchReading> active = all.stream().filter(r -> !r.excluded()).toList();
    BigDecimal mean = null, min = null, max = null;
    if (!active.isEmpty()) {
        BigDecimal sum = BigDecimal.ZERO;
        min = active.get(0).rawReading(); max = min;
        for (var r : active) { sum = sum.add(r.rawReading()); if (r.rawReading().compareTo(min)<0) min=...; }
        mean = sum.divide(BigDecimal.valueOf(active.size()), 12, RoundingMode.HALF_UP);
    }
    BatchStatsRecord record = new BatchStatsRecord(0, batchId, revision, trigger, active.size(),
        all.size() - active.size(), mean, min, max, Instant.now(clock));
    statsRepository.insertStats(record);
    return record;
}
