                                   String reason, int batchRevision, int certificateVersion) {
        Instant now = Instant.now(clock);
        OutlierRecord outlier = outliers.findById(outlierId)
                .orElseThrow(() -> ApiException.notFound("离群记录不存在: " + outlierId));
