        if (batchRevision != batch.revision()) {
            staleReasons.add("测量修订版本已变更: 引用 " + batchRevision + "，当前 " + batch.revision());
        }
        if (certificateVersion != cert.version()) {
            staleReasons.add("证书版本已变更: 引用 " + certificateVersion + "，当前 " + cert.version());
